\version "2.27.2"
% automatically converted by musicxml2ly from 61k-Lyrics-SpannersExtenders.xml
\pointAndClickOff

\header {
  texidoc = "Lyrics spanners: continued syllables and extenders, possibly
    spanning multiple notes.

    In the following, measure-beat values are shown with the assigned MusicXML
    elements. Beat 4 in measure 3 is a rest.

    1/1: Single syllable ‘AAA’ (left-justified), extend.

    1/3: Start syllable ‘bbb’.

    2/2: End syllable ‘CCC’ (right-justified), extend.

    3/1: Single syllable ‘eee’ (left-justified), extend."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c'' {
  \clef "treble" \time 4/4 \key c \major c4 c4 c4 c4 | % 1
  c4 c4 c4 c4 | % 2
  c4 c4 c4 r4 \bar "|."
}

PartPOneVoiceOneLyricsOne = \lyricmode {
  \set ignoreMelismata = ##t
  \set includeGraceNotes = ##t
  AAA __ \skip1 bbb -- \skip1 \skip1 CCC __ \skip1 \skip1 eee __ \skip1 \skip1
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
        \new Lyrics \lyricsto "PartPOneVoiceOne" {
          \PartPOneVoiceOneLyricsOne
        }
      >>
    >>
  >>
  \layout {}
